DROP TABLE IF EXISTS `bak_20260916_warehouse_stock_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `bak_20260916_warehouse_stock_log` (
  `id` bigint NOT NULL DEFAULT '0' COMMENT 'ID',
  `warehouse_id` bigint NOT NULL COMMENT '仓库ID',
  `product_id` bigint DEFAULT NULL COMMENT '产品ID(自有仓成品流水)',
  `material_id` bigint DEFAULT NULL COMMENT '物料ID(委外仓物料流水)',
  `material_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '物料名称',
  `quality_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '品质等级：成品(product_id非空)用 A/B/C/DEFECT/PENDING；委外物料(material_id非空)用 GOOD/DEFECT。两体系互斥，GOOD 仅用于物料',
  `change_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '变动类型',
  `change_quantity` decimal(18,4) DEFAULT '0.0000' COMMENT '变更数量',
  `before_quantity` decimal(18,4) DEFAULT '0.0000' COMMENT '变更前库存',
  `after_quantity` decimal(18,4) DEFAULT '0.0000' COMMENT '变更后库存',
  `related_bill_no` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '关联单据号',
  `related_bill_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '关联单据类型',
  `related_bill_id` bigint DEFAULT NULL COMMENT '关联单据ID',
  `related_delivery_id` bigint DEFAULT NULL COMMENT '关联发货单ID(委外物料流水使用)',
  `related_order_code` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '关联加工单号(委外物料流水使用)',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '备注',
  `company_id` bigint DEFAULT NULL COMMENT '公司ID',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

