DROP TABLE IF EXISTS `after_sale_pending_bak_20260915`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `after_sale_pending_bak_20260915` (
  `id` bigint NOT NULL DEFAULT '0' COMMENT '待整理批次ID',
  `source_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '来源单据类型: SALE_RETURN(销售退单)/SALE_EXCHANGE(销售换货单)',
  `source_id` bigint NOT NULL COMMENT '来源单据ID(sale_return.id / sale_exchange.id)',
  `source_item_id` bigint NOT NULL COMMENT '来源单据明细ID(sale_return_item.id / sale_exchange_item.id)',
  `source_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '来源单号(冗余，便于列表展示与检索)',
  `source_date` date DEFAULT NULL COMMENT '来源单据业务日期(退单的退货日期/换货的换货日期，冗余展示)',
  `warehouse_id` bigint NOT NULL COMMENT '售后仓ID(待分类品所在仓)',
  `customer_id` bigint DEFAULT NULL COMMENT '客户ID(冗余，整理后生成折损应收用)',
  `product_id` bigint NOT NULL COMMENT '产品ID',
  `product_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '产品名称(冗余)',
  `spec` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '规格(冗余)',
  `unit` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '单位(冗余)',
  `quantity` decimal(18,4) DEFAULT '0.0000' COMMENT '待整理数量(来源单据审核时的入库数量)',
  `sorted_quantity` decimal(18,4) DEFAULT '0.0000' COMMENT '已整理数量(整理单审核累加、反审核扣回)',
  `unit_price` decimal(18,4) DEFAULT '0.0000' COMMENT '来源单价(冗余，折损计算与展示用)',
  `company_id` bigint DEFAULT NULL COMMENT '公司ID',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
